"""The shape of the repo, held by tests: no state at the root, every daily step has a plan, every module a test."""
from __future__ import annotations

import re
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

# state that belongs in state/ (docs/RUNBOOK.md, "Where the state lives"); features.db is a committed fixture
STATE_AT_ROOT = ("*.db", "*.db-wal", "*.db-shm", "*.db.lock", "*.csv", "health.json", "dashboard.html", "KILL")
FIXTURES = {"features.db"}
# modules whose test is elsewhere: costs_table is generated by #39/#41, report is covered through the CLI
UNTESTED_OK = {"__init__", "__main__", "costs_table", "report"}


class TestRoot(unittest.TestCase):
    def test_no_state_file_sits_beside_the_code(self):
        stray = sorted(p.name for pat in STATE_AT_ROOT for p in ROOT.glob(pat) if p.name not in FIXTURES)
        self.assertEqual(stray, [], "state at the root: run scripts/move-state.sh")
        self.assertFalse((ROOT / "paper-books").exists(), "paper-books/ belongs in state/")


class TestDailySteps(unittest.TestCase):
    def test_every_step_names_the_plan_it_serves_and_the_plan_exists(self):
        from espero import runner
        source = (ROOT / "espero" / "runner.py").read_text()
        steps = re.findall(r'_step\("([a-z0-9-]+)"', source)
        self.assertGreater(len(steps), 10)
        for name in steps:
            with self.subTest(step=name):
                self.assertIn(name, runner.PLANS, f"{name}: add it to runner.PLANS with the document it serves")
                self.assertTrue((ROOT / runner.PLANS[name]).is_file(), runner.PLANS[name])
        self.assertEqual(sorted(runner.PLANS), sorted(set(steps)), "PLANS lists a step the runner doesn't run")


class TestModules(unittest.TestCase):
    def test_every_module_has_a_test(self):
        tests = "\n".join(p.read_text() for p in (ROOT / "tests").glob("test_*.py"))
        missing = []
        for path in sorted((ROOT / "espero").glob("*.py")):
            m = path.stem
            if m in UNTESTED_OK or (ROOT / "tests" / f"test_{m}.py").exists():
                continue
            if not re.search(rf"espero\.{m}\b|from espero import[^\n]*\b{m}\b", tests):
                missing.append(m)
        self.assertEqual(missing, [])


if __name__ == "__main__":
    unittest.main()
